// Proximity beacon: a mast and a lamp. The lamp glows amber while the nearest
// rover is within RANGE_M and turns dim when none is. Signal 200 is re-emitted
// every tick while lit, so other players' modules can wire to it.
//
// RANGE_M (20 m) is the player's choice, not a fact about Mars.
// The air temperature shown in slot 2 is ENV_AIR_TEMP_K, the typical value for
// the current hour over Mars Year 36 (jezero.temperature.my36_air_hourly_mean),
// not today's weather. Lamp power and heating are not modelled.
import { read, nearest, spawn, pose, remove, state_set, signal_emit, log, fact_tier,
         POS_X, POS_Z, ENV_AIR_TEMP_K, KIND_ROVER, SHAPE_CYLINDER, SHAPE_SPHERE,
         FACT_JEZERO_TEMPERATURE_MY36_AIR_HOURLY_MEAN } from "./host";

const RANGE_M: f32 = 20.0;          // player's detection radius
const SLOT_DIST: i32 = 0;
const SLOT_LIT: i32 = 1;
const SLOT_TEMP: i32 = 2;
const SIGNAL_LIT: i32 = 200;
const LOG_CHANGE: i32 = 40;         // value: rover distance (m) when the lamp switched
const LOG_TIER: i32 = 41;           // value: provenance tier of the temperature record
const LAMP_Y: f32 = 1.65;           // lamp height on the mast (design choice, m)

let mast: i32 = -1;
let lamp: i32 = -1;
let lit: i32 = -1;

function setLamp(on: i32): void {
  if (lamp >= 0) { remove(lamp); lamp = -1; }
  if (on == 1) {
    lamp = spawn(SHAPE_SPHERE, 0.3, 0.3, 0.3, 1.0, 0.65, 0.1);   // bright amber
  } else {
    lamp = spawn(SHAPE_SPHERE, 0.3, 0.3, 0.3, 0.25, 0.2, 0.15);  // dark glass
  }
  if (lamp >= 0) pose(lamp, 0.0, LAMP_Y, 0.0, 0.0, 0.0);
}

export function init(): void {
  mast = spawn(SHAPE_CYLINDER, 0.08, 1.5, 0.08, 0.75, 0.75, 0.75);
  if (mast >= 0) pose(mast, 0.0, 0.75, 0.0, 0.0, 0.0);
  setLamp(0);
  lit = 0;
  log(LOG_TIER, <f32>fact_tier(FACT_JEZERO_TEMPERATURE_MY36_AIR_HOURLY_MEAN));
}

export function tick(dt: f32): void {
  const x = read(POS_X);
  const z = read(POS_Z);
  const d = nearest(KIND_ROVER, x, z);                 // -1 if no rover exists
  const on: i32 = (d >= 0.0 && d <= RANGE_M) ? 1 : 0;

  state_set(SLOT_DIST, d);
  state_set(SLOT_LIT, <f32>on);
  state_set(SLOT_TEMP, read(ENV_AIR_TEMP_K));

  if (on != lit) {
    lit = on;
    setLamp(on);
    log(LOG_CHANGE, d);
  }
  if (on == 1) signal_emit(SIGNAL_LIT, 1.0);           // re-emit every tick while lit
}

